INSERT INTO train_categories(id,title,name,color,sort) VALUES('12132000-0000-4000-8000-000000000001','КМБ','КМБ','#c7a55b',0) ON CONFLICT(id) DO NOTHING;
INSERT INTO train_lessons(title,excerpt,content,category,sort) VALUES('Начало службы','Вводная памятка. Уточняется командованием.','Ознакомьтесь с опубликованным уставом и правилами сервера. Найдите своё подразделение и ответственного инструктора. Уточните порядок построения, доклада и обращения к старшему составу. Практическую проверку проводит инструктор в игре.','12132000-0000-4000-8000-000000000001',0);
INSERT INTO train_categories(id,title,name,color,sort) VALUES('12132000-0000-4000-8000-000000000002','Военная академия','Военная академия','#c7a55b',1) ON CONFLICT(id) DO NOTHING;
INSERT INTO train_lessons(title,excerpt,content,category,sort) VALUES('Работа инструктора','Вводная памятка. Уточняется командованием.','Перед занятием уточните утверждённую тему, состав группы и критерии проверки. Объясните материал, разберите пример и проверьте понимание. Результат экзамена фиксируется отдельно; отметка о прочтении лекции не заменяет сдачу.','12132000-0000-4000-8000-000000000002',0);
INSERT INTO train_categories(id,title,name,color,sort) VALUES('12132000-0000-4000-8000-000000000003','Поставки','Поставки','#c7a55b',2) ON CONFLICT(id) DO NOTHING;
INSERT INTO train_lessons(title,excerpt,content,category,sort) VALUES('Запрос и отчёт поставки','Вводная памятка. Уточняется командованием.','Сначала оформите запрос с получателем, временем и ресурсами. После завершения укажите число выехавших и прибывших машин. Приложите подтверждения. Ответственный проверяет отчёт и отправляет его в Discord.','12132000-0000-4000-8000-000000000003',0);
INSERT INTO train_categories(id,title,name,color,sort) VALUES('12132000-0000-4000-8000-000000000004','Военная полиция','Военная полиция','#c7a55b',3) ON CONFLICT(id) DO NOTHING;
INSERT INTO train_lessons(title,excerpt,content,category,sort) VALUES('Документирование проверки','Вводная памятка. Уточняется командованием.','Фиксируйте дату, участников, основание проверки и ссылки на подтверждения. Указывайте факты отдельно от предположений. Решение и обжалование оформляйте через установленный порядок командования.','12132000-0000-4000-8000-000000000004',0);
INSERT INTO train_categories(id,title,name,color,sort) VALUES('12132000-0000-4000-8000-000000000005','Военный комиссариат','Военный комиссариат','#c7a55b',4) ON CONFLICT(id) DO NOTHING;
INSERT INTO train_lessons(title,excerpt,content,category,sort) VALUES('Приём обращений','Вводная памятка. Уточняется командованием.','Проверьте полноту электронной заявки и направьте кандидата к ответственному сотруднику. Не выдавайте доступ к служебным данным до назначения роли администратором.','12132000-0000-4000-8000-000000000005',0);
INSERT INTO train_categories(id,title,name,color,sort) VALUES('12132000-0000-4000-8000-000000000006','Подразделения','Подразделения','#c7a55b',5) ON CONFLICT(id) DO NOTHING;
INSERT INTO train_lessons(title,excerpt,content,category,sort) VALUES('Учебные материалы подразделений','Вводная памятка. Уточняется командованием.','Для РОиО, ССО и медицинской роты публикуются отдельные материалы и экзамены. Инструктор дополняет этот раздел действующими игровыми регламентами. Эта памятка не устанавливает новые правила сервера.','12132000-0000-4000-8000-000000000006',0);
